#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main() {
    pthread_attr_t attr;
    void *stack_addr = NULL;
    size_t stack_size = 0;
    int ret;

    // 1. Initialize attributes object with defaults
    if ((ret = pthread_attr_init(&attr)) != 0) {
        fprintf(stderr, "pthread_attr_init failed: %d\n", ret);
        return 1;
    }

    // 2. Retrieve default stack configuration
    printf("\n=== Default Stack Configuration ===\n");
    if ((ret = pthread_attr_getstack(&attr, &stack_addr, &stack_size)) != 0) {
        fprintf(stderr, "pthread_attr_getstack failed: %d\n", ret);
        pthread_attr_destroy(&attr);
        return 1;
    }
    printf("Default stack address: %p\n", stack_addr);
    printf("Default stack size: %zu bytes (%zu KB)\n", stack_size, stack_size / 1024);

    // 3. Set a custom stack size (note: only size, address is still system-managed)
    size_t custom_size = 4 * 1024 * 1024; // 4 MB
    if ((ret = pthread_attr_setstacksize(&attr, custom_size)) != 0) {
        fprintf(stderr, "pthread_attr_setstacksize failed: %d\n", ret);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 4. Retrieve the updated stack configuration
    printf("\n=== After Setting Custom Stack Size ===\n");
    stack_addr = NULL;
    stack_size = 0;
    if ((ret = pthread_attr_getstack(&attr, &stack_addr, &stack_size)) != 0) {
        fprintf(stderr, "pthread_attr_getstack failed: %d\n", ret);
        pthread_attr_destroy(&attr);
        return 1;
    }
    printf("Updated stack address: %p\n", stack_addr);
    printf("Updated stack size: %zu bytes (%zu KB)\n", stack_size, stack_size / 1024);

    // 5. Set a fully custom stack with both address and size
    int page_size = sysconf(_SC_PAGESIZE);
    void *custom_addr = NULL;
    size_t custom_stack_size = 2 * 1024 * 1024; // 2 MB

    if ((ret = posix_memalign(&custom_addr, page_size, custom_stack_size)) != 0) {
        fprintf(stderr, "posix_memalign failed: %d\n", ret);
        pthread_attr_destroy(&attr);
        return 1;
    }

    if ((ret = pthread_attr_setstack(&attr, custom_addr, custom_stack_size)) != 0) {
        fprintf(stderr, "pthread_attr_setstack failed: %d\n", ret);
        free(custom_addr);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 6. Retrieve and verify the fully custom stack
    printf("\n=== After Setting Fully Custom Stack ===\n");
    void *retrieved_addr = NULL;
    size_t retrieved_size = 0;
    if ((ret = pthread_attr_getstack(&attr, &retrieved_addr, &retrieved_size)) != 0) {
        fprintf(stderr, "pthread_attr_getstack failed: %d\n", ret);
        free(custom_addr);
        pthread_attr_destroy(&attr);
        return 1;
    }
    printf("Retrieved stack address: %p\n", retrieved_addr);
    printf("Retrieved stack size: %zu bytes (%zu KB)\n", retrieved_size, retrieved_size / 1024);
    printf("\nVerification: Address=%s, Size=%s\n",
           (retrieved_addr == custom_addr) ? "MATCH" : "MISMATCH",
           (retrieved_size == custom_stack_size) ? "MATCH" : "MISMATCH");

    // 7. Clean up
    pthread_attr_destroy(&attr);
    free(custom_addr);

    return 0;
}
